// ⚠ DO NOT REMOVE — bim-compiler prompts/CLI_ERP_IVR.md §41 H1: legacy's document search is DATA, the dictionary table AD_SearchDefinition (AbstractDocumentSearch.getID reads it,
//   MSearchDefinition.getForCode). The seed carries no such table, so it is created here with the pilot's DDL and rows (ad_search_definitions.js, generated by
//   patches/build_search_definitions.py), as an idempotent boot OVERLAY like ad_index_overlay.js: NOT in a hashed patch, so the Team BASE hash does not move.
//   A row an admin changed is kept (INSERT OR IGNORE on the key). ERP_BREAK=nosearchdef skips it (W-RED1-PREFIX falsifier).
(function (global) {
  'use strict';
  function log(m) { try { console.log(m); } catch (e) {} }
  function data() { return global.AD_SEARCH_DEFINITIONS || (typeof module !== 'undefined' && module.exports ? require('./ad_search_definitions.js') : null); }
  // ensure(db) - a sql.js Database. Returns { table, inserted, present, ms }.
  function ensure(db) {
    var t0 = Date.now(), D = data(), ins = 0;
    if (!D) { log('§SEARCHDEF_OVERLAY none (ad_search_definitions.js not loaded)'); return { table: null, inserted: 0, present: 0, ms: 0 }; }
    var cs = D.columns.map(function (c) { return c[0]; });
    db.run('CREATE TABLE IF NOT EXISTS ' + D.table + ' (' + D.columns.map(function (c) { return c[0] + ' ' + c[1]; }).join(', ') + (D.pk.length ? ', PRIMARY KEY (' + D.pk.join(', ') + ')' : '') + ')');
    var before = Number(db.exec('SELECT count(*) FROM ' + D.table)[0].values[0][0]);
    D.rows.forEach(function (r) { db.run('INSERT OR IGNORE INTO ' + D.table + ' (' + cs.join(',') + ') VALUES (' + cs.map(function () { return '?'; }).join(',') + ')', cs.map(function (c) { return r[c] == null ? null : r[c]; })); });
    var after = Number(db.exec('SELECT count(*) FROM ' + D.table)[0].values[0][0]); ins = after - before;
    log('§SEARCHDEF_OVERLAY ensure table=' + D.table + ' inserted=' + ins + ' present=' + before + ' rows=' + after + ' ms=' + (Date.now() - t0) + ' (legacy AD_SearchDefinition; boot overlay, outside the team base hash)');
    return { table: D.table, inserted: ins, present: before, ms: Date.now() - t0 };
  }
  var API = { ensure: ensure, data: data };
  if (typeof module !== 'undefined' && module.exports) module.exports = API;
  global.AdSearchOverlay = API;
})(typeof window !== 'undefined' ? window : globalThis);
